param([string]$FixtureDirectory,[string]$OnlyCase)
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '..\..\System\Shared\Core.ps1')
$root=$script:ProjectRoot
$tokens=$null;$issues=$null;$ast=[Management.Automation.Language.Parser]::ParseFile((Join-Path $PSScriptRoot 'Test-Expansion.ps1'),[ref]$tokens,[ref]$issues)
# Reuse only the trusted test process/assertion helpers, never rerun its suite.
foreach($function in $ast.EndBlock.Statements|Where-Object {$_ -is [Management.Automation.Language.FunctionDefinitionAst] -and $_.Name -in @('Run-Bat','Assert','Record','HashTree','Probe','Image-Info','PDF-Count')}){. ([scriptblock]::Create($function.Extent.Text))}
if(-not $FixtureDirectory){$last=Get-ChildItem -LiteralPath (Join-Path $PSScriptRoot '_work') -Directory -Filter 'e-*'|Sort-Object CreationTime -Descending|Select-Object -First 1;$FixtureDirectory=Join-Path $last.FullName 'f'}
$fixtureSource=[IO.Path]::GetFullPath($FixtureDirectory)
$ff=Require-Dependency ffmpeg;$probe=Require-Dependency ffprobe;$magick=Require-Dependency magick;$gs=Require-Dependency ghostscript
$catalog=Get-Content -LiteralPath (Join-Path $root 'System\Shared\tools.json') -Raw -Encoding UTF8|ConvertFrom-Json
$work=Join-Path $PSScriptRoot ('_work\o-'+[guid]::NewGuid().ToString('N').Substring(0,8));Ensure-Directory $work
$fixtures=Join-Path $work 'f';Ensure-Directory $fixtures;$script:NativeWorkingDirectory=$fixtures
foreach($file in @('colors.png','changed.png','pattern.png','pattern.jpg','logo.png','video.mp4','bars.mp4','text.srt','tone.wav','silence.wav','pages.pdf','notes.txt','table.csv')){[IO.File]::Copy((Join-Path $fixtureSource $file),(Join-Path $fixtures $file),$false)}
$arabic=-join([char[]]@(0x0639,0x0631,0x0628,0x064A));$results=New-Object 'Collections.Generic.List[object]';$script:CaseId=0
function Case([string]$Name,[string]$Tool,[scriptblock]$Prepare,[scriptblock]$Inspect,[bool]$AllowRename=$false){
 if($OnlyCase -and $Name -notmatch $OnlyCase){return}
 try{
  $script:CaseId++;$caseRoot=Join-Path $work ($arabic+' ! & %X% ['+$script:CaseId+']');Ensure-Directory (Join-Path $caseRoot 'System')
  Copy-Item -LiteralPath (Join-Path $root 'System\Shared') -Destination (Join-Path $caseRoot 'System\Shared') -Recurse
  $entry=$catalog|Where-Object Name -eq $Tool;$script:bat=Join-Path $caseRoot $entry.Path;$script:dir=Split-Path $script:bat
  Ensure-Directory $script:dir
  foreach($ext in @('.bat','.ps1','.md')){[IO.File]::Copy([IO.Path]::ChangeExtension((Join-Path $root $entry.Path),$ext),[IO.Path]::ChangeExtension($script:bat,$ext),$false)}
  $script:inputDir=Join-Path $script:dir 'Input';$script:output=Join-Path $script:dir 'Output';Ensure-Directory $script:inputDir;Ensure-Directory $script:output
  & $Prepare;$hash=HashTree $script:inputDir;& $Inspect
  if(-not $AllowRename){Assert ((HashTree $script:inputDir) -eq $hash) 'Source tree changed.'}
  Record $Name $true 'Real interactive BAT; option-specific content/result and source safety verified in isolated fixtures.'
 }catch{Record $Name $false $_.Exception.Message}
}
function Put([string]$File,[string]$Relative){$target=Join-Path $script:inputDir $Relative;Ensure-Directory ([IO.Path]::GetDirectoryName($target));[IO.File]::Copy((Join-Path $fixtures $File),$target,$false)}
function Good([string]$Answers){$run=Run-Bat $script:bat '' $Answers;Assert ($run.Code -eq 0 -and $run.Text -match '\[SUCCESS\]') $run.Text;$run.Text}
function Bad([string]$Answers){$run=Run-Bat $script:bat '' $Answers;Assert ($run.Code -in @(1,2) -and -not @(Get-SafeFiles $script:output $null -Recurse).Count) ('Invalid option accepted: '+$run.Text)}
function Output-File([string]$Extension){@(Get-SafeFiles $script:output @($Extension) -Recurse)[0].FullName}
function PDF-Text([string]$Path){[IO.File]::Copy($Path,(Join-Path $fixtures 'options.pdf'),$true);[void](Invoke-Checked $gs @('-q','-dSAFER','-dBATCH','-dNOPAUSE','-sDEVICE=txtwrite','-sOutputFile=options.txt','options.pdf'));[IO.File]::ReadAllText((Join-Path $fixtures 'options.txt'))}
Case 'Compare rejects incompatible dimensions' 'Image Compare' {Put 'colors.png' 'Left\one.png';Put 'pattern.jpg' 'Right\two.jpg'} {Bad "1`n"}
Case 'Collage top template' 'Image Collage' {Put 'colors.png' '001.png';Put 'pattern.png' '002.png';Put 'changed.png' '003.png'} {$null=Good "2`n";Assert ((Image-Info (Output-File '.png')) -eq '1200 1000') 'Top collage geometry wrong.'}
Case 'Collage custom canvas and color' 'Image Collage' {Put 'colors.png' '001.png';Put 'pattern.png' '002.png';Put 'changed.png' '003.png'} {$null=Good "3`n600`n10`n#112233`n";Assert ((Image-Info (Output-File '.png')) -eq '600 400') 'Custom geometry wrong.';$color=Invoke-Checked $magick @('checked.png','-format','%[pixel:p{0,0}]','info:');Assert ($color -match '17,34,51|6.6667%,13.3333%,20%') ('Wrong background '+$color)}
Case 'Palette single color' 'Image Color Palette' {Put 'logo.png' 'one.png'} {$null=Good "3`n";$rows=@(Import-Csv -LiteralPath (Join-Path $output 'one.png.palette\colors.csv'));Assert ($rows.Count -eq 1 -and [int]$rows[0].Pixels -eq 400) 'Single-color palette wrong.'}
Case 'PDF image landscape option' 'Image to PDF' {Put 'colors.png' 'one.png'} {$null=Good "2`n";Assert ((PDF-Count (Output-File '.pdf')) -eq 1) 'Missing page.';$info=Invoke-Checked $gs @('-dSAFER','-dBATCH','-dNOPAUSE','-dPDFINFO','-sDEVICE=nullpage','checked.pdf');Assert ($info -match 'MediaBox: \[0 0 8\d\d\.\d+ 5\d\d\.\d+\]') 'A4 landscape box wrong.'}
Case 'Merge normalizes incompatible inputs' 'Video Merge' {Put 'video.mp4' '001.mp4';Put 'bars.mp4' '002.mp4'} {$text=Good "1`n";$p=Probe (Output-File '.mp4');Assert ($text -match 'Re-encoding' -and $p.streams[0].width -eq 1280 -and $p.streams[0].height -eq 720 -and [double]$p.format.duration -gt 3.9) 'Normalization or merged duration wrong.'}
Case 'Merge copy-only refuses incompatible tracks' 'Video Merge' {Put 'video.mp4' '001.mp4';Put 'bars.mp4' '002.mp4'} {Bad "3`n"}
Case 'Merge normalization respects anamorphic display aspect' 'Video Merge' {[void](Invoke-Checked $ff @('-v','error','-nostdin','-y','-i','video.mp4','-vf','setsar=2/1','-c:v','libx264','-c:a','copy','options-sar.mp4'));Put 'options-sar.mp4' '001.mp4';Put 'options-sar.mp4' '002.mp4'} {$null=Good "2`n";$crop=Invoke-Native $ff @('-hide_banner','-nostdin','-i',(Output-File '.mp4'),'-vf','cropdetect=limit=24:round=2','-an','-f','null','-');$rectangles=@([regex]::Matches($crop.Err,'crop=(\d+):(\d+):'));Assert ($rectangles.Count -gt 0 -and [int]$rectangles[-1].Groups[1].Value -gt 1200 -and [int]$rectangles[-1].Groups[2].Value -lt 500) 'Normalization distorted the anamorphic display aspect ratio.'}
Case 'Merge normalizes PCM audio incompatible with MP4' 'Video Merge' {[void](Invoke-Checked $ff @('-v','error','-nostdin','-y','-i','video.mp4','-c:v','copy','-c:a','pcm_s16le','options-pcm.mkv'));Put 'options-pcm.mkv' '001.mkv';Put 'options-pcm.mkv' '002.mkv'} {$text=Good "1`n";$p=Probe (Output-File '.mp4');Assert ($text -match 'Re-encoding' -and @($p.streams|Where-Object {$_.codec_type -eq 'audio' -and $_.codec_name -eq 'aac'}).Count -eq 1) 'Unsupported MP4 audio was incorrectly copied.'}
Case 'Screenshot custom time' 'Video Screenshot at Time' {Put 'video.mp4' 'clip.mp4'} {$null=Good "2`n0.5`n";[void](Invoke-Checked $ff @('-v','error','-nostdin','-y','-i','video.mp4','-ss','0.5','-frames:v','1','options-time.png'));$a=Invoke-Checked $ff @('-v','error','-i','options-time.png','-f','md5','-');$b=Invoke-Checked $ff @('-v','error','-i',(Output-File '.png'),'-f','md5','-');Assert ($a.Trim() -eq $b.Trim()) 'Custom screenshot time ignored.'}
Case 'Screenshot out-of-range refused' 'Video Screenshot at Time' {Put 'video.mp4' 'clip.mp4'} {Bad "2`n1000`n"}
Case 'Watermark custom position and opacity' 'Video Watermark' {Put 'video.mp4' 'clip.mp4';Ensure-Directory (Join-Path $dir 'Watermark');[IO.File]::Copy((Join-Path $fixtures 'logo.png'),(Join-Path $dir 'Watermark\logo.png'))} {$null=Good "3`n1`n10`n100`n";[void](Invoke-Checked $ff @('-v','error','-nostdin','-y','-i',(Output-File '.mp4'),'-frames:v','1','options-logo.png'));$green=Invoke-Checked $magick @('options-logo.png','-format','%[fx:p{2,2}.g]','info:');Assert ([double]$green -gt 0.8) 'Custom logo position/opacity ignored.'}
Case 'Subtitle track copies video bitstream' 'Video Add Subtitle Track' {Put 'video.mp4' 'clip.mp4';Put 'text.srt' 'Subtitles\clip.srt'} {$null=Good "1`n";$a=Invoke-Checked $ff @('-v','error','-i','video.mp4','-map','0:v:0','-c:v','copy','-f','md5','-');$b=Invoke-Checked $ff @('-v','error','-i',(Output-File '.mkv'),'-map','0:v:0','-c:v','copy','-f','md5','-');Assert ($a.Trim() -eq $b.Trim()) 'Video re-encoded while adding subtitles.'}
Case 'Black-bar crop declined' 'Video Remove Black Bars' {Put 'bars.mp4' 'clip.mp4'} {$null=Good "2`nN`n";Assert (-not @(Get-SafeFiles $output @('.mp4') -Recurse).Count) 'Declined crop still wrote a video.'}
Case 'Black-bar crop explicit APPLY' 'Video Remove Black Bars' {Put 'bars.mp4' 'clip.mp4'} {$null=Good "2`nAPPLY`n";$p=Probe (Output-File '.mp4');Assert ($p.streams[0].width -eq 64 -and $p.streams[0].height -eq 32) 'Approved crop dimensions wrong.'}
Case 'Black-bar detection handles rotated display' 'Video Remove Black Bars' {[void](Invoke-Checked $ff @('-v','error','-nostdin','-y','-display_rotation','90','-i','bars.mp4','-c','copy','options-rotated.mp4'));Put 'options-rotated.mp4' 'clip.mp4'} {$null=Good "1`n";$row=Import-Csv -LiteralPath (Join-Path $output 'clip.mp4.crop-preview\crop.csv');Assert ($row.OriginalWidth -eq '64' -and $row.OriginalHeight -eq '96' -and $row.CropWidth -eq '32' -and $row.CropHeight -eq '64') 'Rotated display dimensions/crop wrong.'}
Case 'Watermark handles rotated display dimensions' 'Video Watermark' {[void](Invoke-Checked $ff @('-v','error','-nostdin','-y','-display_rotation','90','-i','video.mp4','-c','copy','options-rotated-logo.mp4'));Put 'options-rotated-logo.mp4' 'clip.mp4';Ensure-Directory (Join-Path $dir 'Watermark');[IO.File]::Copy((Join-Path $fixtures 'logo.png'),(Join-Path $dir 'Watermark\logo.png'))} {$null=Good "1`n";$p=Probe (Output-File '.mp4');Assert ($p.streams[0].width -eq 64 -and $p.streams[0].height -eq 96) 'Watermark ignored display rotation.'}
Case 'Audio sync negative offset pads the tail' 'Video Audio Sync' {Put 'video.mp4' 'clip.mp4'} {$null=Good "2`n-0.500`n";$out=Output-File '.mkv';$vol=Invoke-Native $ff @('-v','info','-ss','1.8','-i',$out,'-af','volumedetect','-f','null','-');Assert ($vol.Err -match 'mean_volume: (-inf|-[789]\d(?:\.\d+)?) dB') 'Negative offset did not pad trailing silence.'}
Case 'Invalid sync value refused' 'Video Audio Sync' {Put 'video.mp4' 'clip.mp4'} {Bad "2`n0&whoami`n"}
Case 'Audio to video with still image' 'Audio to Video' {Put 'tone.wav' 'voice.wav';Put 'colors.png' 'Picture\still.png'} {$null=Good "2`n";$p=Probe (Output-File '.mp4');Assert ($p.streams[0].width -eq 1280 -and [Math]::Abs([double]$p.format.duration-2) -lt 0.2) 'Still-image video wrong.'}
Case 'Remove internal silence' 'Audio Remove Silence' {Put 'silence.wav' 'voice.wav'} {$null=Good "2`n";$d=[double](Probe (Output-File '.wav')).format.duration;Assert ($d -gt 1.9 -and $d -lt 2.5) 'Internal silence not removed as documented.'}
Case 'Silence split minimum prevents tiny clips' 'Audio Split by Silence' {Put 'silence.wav' 'voice.wav'} {$null=Good "2`n45`n0.7`n5`n";$rows=@(Import-Csv -LiteralPath (Join-Path $output 'voice.wav.segments\segments.csv'));Assert ($rows.Count -eq 1 -and [double]$rows[0].Duration -gt 2.9) 'Minimum-clip guard lost content.'}
[void](Invoke-Checked $ff @('-v','error','-nostdin','-n','-f','lavfi','-i','anullsrc=r=8000:cl=mono','-t','601','-c:a','flac','options-long.flac'))
Case 'Reverse refuses oversized buffered job' 'Audio Reverse' {Put 'options-long.flac' 'long.flac'} {Bad "1`n"}
Case 'PDF selected rotation preserves other pages' 'PDF Rotate Pages' {Put 'pages.pdf' 'book.pdf'} {$null=Good "2`n2`n1`n";Assert ((PDF-Count (Output-File '.pdf')) -eq 3) 'Lost page.';$info=Invoke-Checked $gs @('-dSAFER','-dBATCH','-dNOPAUSE','-dPDFINFO','-sDEVICE=nullpage','checked.pdf');Assert ($info -match 'Page 1 MediaBox: \[0 0 300 400\]' -and $info -match 'Page 2 MediaBox: \[0 0 400 300\]' -and $info -match 'Page 3 MediaBox: \[0 0 300 400\]') 'Unselected page geometry changed.'}
foreach($angle in 1..3){Case ('PDF rotation pixel direction '+$angle) 'PDF Rotate Pages' {Put 'pages.pdf' 'book.pdf'} {
 $null=Good ("2`n1`n"+$angle+"`n");$out=Output-File '.pdf';[IO.File]::Copy($out,(Join-Path $fixtures 'angle.pdf'),$true)
 [void](Invoke-Checked $gs @('-q','-dSAFER','-dBATCH','-dNOPAUSE','-sDEVICE=png16m','-r72','-dFirstPage=1','-dLastPage=1','-sOutputFile=angle-original.png','pages.pdf'))
 [void](Invoke-Checked $gs @('-q','-dSAFER','-dBATCH','-dNOPAUSE','-sDEVICE=png16m','-r72','-dFirstPage=1','-dLastPage=1','-sOutputFile=angle-actual.png','angle.pdf'))
 [void](Invoke-Checked $magick @('angle-original.png','-rotate',([string]($angle*90)),'angle-expected.png'))
 $compare=Invoke-Native $magick @('compare','-metric','RMSE','angle-expected.png','angle-actual.png','null:')
 Assert ($compare.Code -in @(0,1) -and $compare.Err -match '\(([0-9.eE+-]+)\)' -and [double]$Matches[1] -lt 0.02) ('Rendered rotation differs from requested clockwise angle: '+$compare.Err)
}}
Case 'PDF extract nonsequential order' 'PDF Extract Pages' {Put 'pages.pdf' 'book.pdf'} {$null=Good "2`n3,1`n";$pdf=Output-File '.pdf';Assert ((PDF-Count $pdf) -eq 2) 'Wrong selected count.';$t=PDF-Text $pdf;Assert ($t.Contains('PAGE THREE') -and $t.IndexOf('PAGE THREE') -lt $t.IndexOf('PAGE ONE') -and -not $t.Contains('PAGE TWO')) 'Requested extraction order ignored.'}
foreach($selection in @('0','4','1,1','3-1')){Case ('PDF invalid selection '+$selection) 'PDF Extract Pages' {Put 'pages.pdf' 'book.pdf'} {Bad ("2`n"+$selection+"`n")}}
Case 'PDF complete custom permutation' 'PDF Reorder Pages' {Put 'pages.pdf' 'book.pdf'} {$null=Good "2`n3,1,2`n";$t=PDF-Text (Output-File '.pdf');Assert ($t.IndexOf('PAGE THREE') -lt $t.IndexOf('PAGE ONE') -and $t.IndexOf('PAGE ONE') -lt $t.IndexOf('PAGE TWO')) 'Custom permutation wrong.'}
Case 'PDF reorder refuses omitted pages' 'PDF Reorder Pages' {Put 'pages.pdf' 'book.pdf'} {Bad "2`n1,2`n"}
Case 'Rename literal replacement' 'Batch Rename' {Put 'notes.txt' 'draft-notes.txt'} {$null=Good "3`ndraft`nfinal`n";Assert (Test-Path -LiteralPath (Join-Path $output 'rename-plan\Copies\final-notes.txt')) 'Literal rename pattern ignored.'}
Case 'Rename collision refused' 'Batch Rename' {Put 'notes.txt' 'draft-notes.txt';Put 'table.csv' 'notes.txt'} {Bad "3`ndraft-`n`n"}
Case 'Rename original mode declined' 'Batch Rename' {Put 'notes.txt' 'notes.txt'} {$null=Good "5`n1`nnew_`nN`n";Assert ([IO.File]::ReadAllText((Join-Path $output 'rename-plan\status.txt')) -match 'declined') 'Original-rename refusal ignored.'}
Case 'Rename originals explicit consent and backups' 'Batch Rename' {Put 'notes.txt' 'notes.txt';Put 'table.csv' 'data.csv'} {$sourceHash=(Get-FileHash -LiteralPath (Join-Path $inputDir 'notes.txt')).Hash;$null=Good "5`n1`nnew_`nRENAME ORIGINALS`n";Assert (-not (Test-Path -LiteralPath (Join-Path $inputDir 'notes.txt')) -and (Get-FileHash -LiteralPath (Join-Path $inputDir 'new_notes.txt')).Hash -eq $sourceHash -and (Get-FileHash -LiteralPath (Join-Path $output 'rename-plan\Originals\notes.txt')).Hash -eq $sourceHash) 'Rename/backup bytes wrong.'} $true
Case 'Largest-files custom read-only scope' 'Find Large Files' {Put 'notes.txt' 'unused.txt'} {$before=HashTree $fixtures;$null=Good ("2`n"+$fixtures+"`n1`n");$rows=@(Import-Csv -LiteralPath (Join-Path $output 'large-files\largest-files.csv'));Assert ($rows.Count -eq 1 -and [long]$rows[0].Bytes -gt 1000 -and (HashTree $fixtures) -eq $before) 'Custom read-only scope or top count wrong.'}
Case 'Empty report respects hidden content' 'Empty Folders Report' {Ensure-Directory (Join-Path $inputDir 'Empty');Ensure-Directory (Join-Path $inputDir 'Hidden');Put 'notes.txt' 'Hidden\secret.txt';(Get-Item -LiteralPath (Join-Path $inputDir 'Hidden\secret.txt')).Attributes='Hidden'} {$null=Good "1`n";$rows=@(Import-Csv -LiteralPath (Join-Path $output 'empty-folders.csv'));Assert ($rows.Count -eq 1 -and $rows[0].Path -eq 'Empty') 'Hidden content treated as empty.'}
Case 'Text replacement explicit WRITE preserves UTF16' 'Text Find and Replace' {Put 'notes.txt' 'notes.txt'} {$null=Good "2`nTODO`nDONE`nWRITE`n";$path=Join-Path $output 'replacements\Copies\notes.txt';$bytes=[IO.File]::ReadAllBytes($path);$text=[IO.File]::ReadAllText($path);Assert ($bytes[0] -eq 255 -and $bytes[1] -eq 254 -and $text.Contains($arabic) -and $text.Contains("`r`n") -and -not $text.Contains('TODO') -and $text.Contains('DONE')) 'Text encoding/content not preserved.'}
Case 'Text replacement declined' 'Text Find and Replace' {Put 'notes.txt' 'notes.txt'} {$null=Good "2`nTODO`nDONE`nN`n";Assert (-not (Test-Path -LiteralPath (Join-Path $output 'replacements\Copies'))) 'Declined WRITE still produced copies.'}
Case 'CSV UTF16 semicolon quoted multiline' 'CSV to JSON' {$text='"Name";"Value"'+"`r`n"+'"'+$arabic+'";"multi'+"`r`n"+'line; value"';[IO.File]::WriteAllText((Join-Path $inputDir 'table.csv'),$text,(New-Object Text.UnicodeEncoding($true,$true,$true)))} {$null=Good "2`n";$j=Get-Content -LiteralPath (Output-File '.json') -Raw -Encoding UTF8|ConvertFrom-Json;Assert ($j[0].Name -ceq $arabic -and $j[0].Value -ceq "multi`r`nline; value") 'UTF16/delimiter/quoted multiline CSV changed.'}
Case 'JSON string table to CSV round trip' 'CSV to JSON' {$row=[pscustomobject]@{Name=$arabic;Number='123456789012345678901234567890';Note="line1`r`nline2, `"quoted`""};ConvertTo-Json -InputObject @($row)|Set-Content -LiteralPath (Join-Path $inputDir 'table.json') -Encoding UTF8} {$null=Good "3`n";$rows=@(Import-Csv -LiteralPath (Output-File '.csv') -Encoding UTF8);Assert ($rows[0].Name -ceq $arabic -and $rows[0].Number -ceq '123456789012345678901234567890' -and $rows[0].Note.Contains("`r`n") -and $rows[0].Note.Contains('"quoted"')) 'JSON-to-CSV changed string values.'}
Case 'JSON numeric reverse refused without rounding' 'CSV to JSON' {[IO.File]::WriteAllText((Join-Path $inputDir 'big.json'),'[{"n":123456789012345678901234567890}]')} {Bad "3`n"}
$report=if($OnlyCase){'expansion-options-focused-results.json'}else{'expansion-options-results.json'}
[pscustomobject]@{DateUTC=[datetime]::UtcNow.ToString('o');Results=$results}|ConvertTo-Json -Depth 6|Set-Content -LiteralPath (Join-Path $PSScriptRoot $report) -Encoding UTF8
Write-Host ('Passed '+@($results|Where-Object Passed).Count+'; Failed '+@($results|Where-Object {-not $_.Passed}).Count)
if(@($results|Where-Object {-not $_.Passed}).Count){exit 1};exit 0
